import { requireTenantPermission } from './tenant.js';
import { appendAuditLedger } from './audit.js';
import { ensureHrPayrollSchema } from './hr-payroll-schema.js';
import { ATLAS_VERSION } from './version.js';

const PERSON_TYPES=new Set(['employee','candidate','contractor','intern','volunteer']);
const PERSON_STATUSES=new Set(['active','onboarding','inactive','offboarded','rejected']);
const EMPLOYMENT_TYPES=new Set(['full_time','part_time','temporary','contract','intern','volunteer']);
const PAY_TYPES=new Set(['hourly','salary','unpaid']);
const PAY_SCHEDULES=new Set(['weekly','biweekly','semimonthly','monthly']);
const APP_STAGES=new Set(['applied','screening','interview','assessment','offer','hired','rejected','withdrawn']);
const json=(body,status=200)=>Response.json(body,{status,headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
const html=(body,status=200)=>new Response(body,{status,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','content-security-policy':"default-src 'self'; img-src 'self' data:; style-src 'unsafe-inline'; script-src 'unsafe-inline' 'self'; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"}});
function text(v,max=240){return String(v??'').trim().replace(/\s+/g,' ').slice(0,max)}
function nullableText(v,max=500){const x=text(v,max);return x||null}
function isoDate(v){const x=text(v,10);return /^\d{4}-\d{2}-\d{2}$/.test(x)?x:null}
function safeInt(v,{min=Number.MIN_SAFE_INTEGER,max=Number.MAX_SAFE_INTEGER}={}){const n=Number(v);return Number.isSafeInteger(n)&&n>=min&&n<=max?n:null}
function email(v){const x=text(v,254).toLowerCase();return !x?null:/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x)?x:null}
async function bodyJson(request,maxBytes=131072){const raw=await request.text();if(raw.length>maxBytes)return{ok:false,status:413,error:'payload_too_large'};if(!raw.trim())return{ok:true,body:{}};try{return{ok:true,body:JSON.parse(raw)}}catch{return{ok:false,status:400,error:'invalid_json'}}}
async function authorize(request,env,permission,action){const authz=await requireTenantPermission(request,env,permission,action);if(!authz.ok)return{response:json({ok:false,error:authz.error},authz.status)};try{const schema=await ensureHrPayrollSchema(env);if(!schema.ok)return{response:json({ok:false,error:schema.error},503)}}catch{return{response:json({ok:false,error:'hr_payroll_schema_unavailable'},503)}}return{authz}}
async function auditMutation(env,authz,action,resourceType,resourceId,metadata=null){try{await appendAuditLedger(env,{organizationId:authz.organizationId,dbaId:authz.dbaId,actorUserId:authz.session.user_id,category:'hr_payroll',action,resourceType,resourceId,decision:'allow',severity:'info',correlationId:authz.correlationId,metadata});return true}catch{return false}}
async function personInScope(env,authz,id){return env.DB.prepare(`SELECT * FROM hr_people WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first()}
async function recomputePayRun(env,runId){const row=await env.DB.prepare(`SELECT COALESCE(SUM(gross_cents),0) AS gross,COALESCE(SUM(pretax_deductions_cents+posttax_deductions_cents),0) AS deductions,COALESCE(SUM(employee_tax_cents),0) AS taxes,COALESCE(SUM(net_cents),0) AS net FROM hr_pay_run_items WHERE pay_run_id=?`).bind(runId).first();await env.DB.prepare(`UPDATE hr_pay_runs SET gross_cents=?,deductions_cents=?,employee_tax_cents=?,net_cents=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(Number(row?.gross||0),Number(row?.deductions||0),Number(row?.taxes||0),Number(row?.net||0),runId).run();return{grossCents:Number(row?.gross||0),deductionsCents:Number(row?.deductions||0),employeeTaxCents:Number(row?.taxes||0),netCents:Number(row?.net||0)}}

async function overview(request,env){const gate=await authorize(request,env,'module.read','hr_payroll.overview.read');if(gate.response)return gate.response;const{authz}=gate;const [people,jobs,time,pay,onboarding]=await env.DB.batch([env.DB.prepare(`SELECT COUNT(*) AS total,SUM(CASE WHEN person_type='employee' AND status IN ('active','onboarding') THEN 1 ELSE 0 END) AS employees,SUM(CASE WHEN person_type='candidate' AND status!='rejected' THEN 1 ELSE 0 END) AS candidates FROM hr_people WHERE organization_id=? AND dba_id=?`).bind(authz.organizationId,authz.dbaId),env.DB.prepare(`SELECT COUNT(*) AS total FROM hr_jobs WHERE organization_id=? AND dba_id=? AND status='open'`).bind(authz.organizationId,authz.dbaId),env.DB.prepare(`SELECT COUNT(*) AS pending FROM hr_time_entries WHERE organization_id=? AND dba_id=? AND status='submitted'`).bind(authz.organizationId,authz.dbaId),env.DB.prepare(`SELECT COUNT(*) AS pending,COALESCE(SUM(net_cents),0) AS net FROM hr_pay_runs WHERE organization_id=? AND dba_id=? AND status IN ('draft','calculated','approved')`).bind(authz.organizationId,authz.dbaId),env.DB.prepare(`SELECT COUNT(*) AS open FROM hr_onboarding_tasks WHERE organization_id=? AND dba_id=? AND status NOT IN ('completed','waived')`).bind(authz.organizationId,authz.dbaId)]);return json({ok:true,overview:{people:Number(people.results?.[0]?.total||0),employees:Number(people.results?.[0]?.employees||0),candidates:Number(people.results?.[0]?.candidates||0),openJobs:Number(jobs.results?.[0]?.total||0),timeAwaitingApproval:Number(time.results?.[0]?.pending||0),payRunsPending:Number(pay.results?.[0]?.pending||0),pendingNetCents:Number(pay.results?.[0]?.net||0),onboardingOpen:Number(onboarding.results?.[0]?.open||0)}})}

async function listEmployees(request,env){const gate=await authorize(request,env,'module.read','hr.employees.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT p.id,p.person_type,p.employee_number,p.first_name,p.last_name,p.display_name,p.email,p.department,p.job_title,p.status,p.hired_at,e.id AS employment_profile_id,e.position_id,pos.code AS position_code,pos.title AS position_title,e.employment_status,e.pay_type,e.hourly_rate_cents,e.annual_salary_cents,e.overtime_eligible,e.standard_hours_week,e.pay_schedule,e.manager_person_id FROM hr_people p LEFT JOIN hr_employment_profiles e ON e.person_id=p.id AND e.organization_id=p.organization_id AND e.dba_id=p.dba_id LEFT JOIN hr_positions pos ON pos.id=e.position_id WHERE p.organization_id=? AND p.dba_id=? AND p.person_type IN ('employee','contractor','intern','volunteer') ORDER BY p.status,p.display_name`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,employees:rows.results||[]})}
async function createEmployee(request,env){const gate=await authorize(request,env,'module.write','hr.employee.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,first=text(b.firstName,100),last=text(b.lastName,100),display=text(b.displayName||`${first} ${last}`,220),personType=text(b.personType||'employee',32),status=text(b.status||'onboarding',32),normalizedEmail=b.email?email(b.email):null;if(!first||!last||display.length<2||!PERSON_TYPES.has(personType)||!PERSON_STATUSES.has(status)||(b.email&&!normalizedEmail))return json({ok:false,error:'valid_employee_fields_required'},400);const id=crypto.randomUUID();try{await env.DB.prepare(`INSERT INTO hr_people(id,organization_id,dba_id,person_type,employee_number,first_name,last_name,display_name,email,department,job_title,status,hired_at,created_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,authz.organizationId,authz.dbaId,personType,nullableText(b.employeeNumber,80),first,last,display,normalizedEmail,nullableText(b.department,160),nullableText(b.jobTitle,160),status,b.hiredAt?isoDate(b.hiredAt):null,authz.session.user_id).run()}catch{return json({ok:false,error:'employee_create_conflict'},409)}const auditRecorded=await auditMutation(env,authz,'hr.employee.create','hr_person',id,{personType,status});return json({ok:true,employee:{id,displayName:display,personType,status},auditRecorded},201)}

async function listPositions(request,env){const gate=await authorize(request,env,'module.read','hr.positions.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT id,code,title,department,employment_type,status,created_at FROM hr_positions WHERE organization_id=? AND dba_id=? ORDER BY status DESC,department,title`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,positions:rows.results||[]})}
async function createPosition(request,env){const gate=await authorize(request,env,'module.write','hr.position.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,code=text(b.code,40).toUpperCase(),title=text(b.title,160),type=text(b.employmentType||'full_time',30);if(!code||title.length<2||!EMPLOYMENT_TYPES.has(type))return json({ok:false,error:'valid_position_fields_required'},400);const id=crypto.randomUUID();try{await env.DB.prepare(`INSERT INTO hr_positions(id,organization_id,dba_id,code,title,department,employment_type,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,'active',?)`).bind(id,authz.organizationId,authz.dbaId,code,title,nullableText(b.department,160),type,authz.session.user_id).run()}catch{return json({ok:false,error:'position_code_conflict'},409)}const auditRecorded=await auditMutation(env,authz,'hr.position.create','hr_position',id,{code,title});return json({ok:true,position:{id,code,title,employmentType:type,status:'active'},auditRecorded},201)}

async function upsertEmployment(request,env,personId){const gate=await authorize(request,env,'module.write','hr.employment.upsert');if(gate.response)return gate.response;const{authz}=gate,person=await personInScope(env,authz,personId);if(!person)return json({ok:false,error:'employee_not_found'},404);const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,payType=text(b.payType||'hourly',20),schedule=text(b.paySchedule||'biweekly',20),employmentStatus=text(b.employmentStatus||'active',20),hourly=b.hourlyRateCents==null?null:safeInt(b.hourlyRateCents,{min:0}),salary=b.annualSalaryCents==null?null:safeInt(b.annualSalaryCents,{min:0}),overtime=b.overtimeEligible===false||b.overtimeEligible===0?0:1,hours=Number(b.standardHoursWeek??40),positionId=nullableText(b.positionId,128),managerId=nullableText(b.managerPersonId,128),hireDate=b.hireDate?isoDate(b.hireDate):null;if(!PAY_TYPES.has(payType)||!PAY_SCHEDULES.has(schedule)||!['active','on_leave','terminated'].includes(employmentStatus)||!Number.isFinite(hours)||hours<0||hours>168||(payType==='hourly'&&hourly==null)||(payType==='salary'&&salary==null)||(b.hireDate&&!hireDate))return json({ok:false,error:'valid_employment_fields_required'},400);if(positionId){const pos=await env.DB.prepare(`SELECT id FROM hr_positions WHERE id=? AND organization_id=? AND dba_id=? AND status='active'`).bind(positionId,authz.organizationId,authz.dbaId).first();if(!pos)return json({ok:false,error:'position_not_found'},404)}if(managerId&&!await personInScope(env,authz,managerId))return json({ok:false,error:'manager_not_found'},404);const existing=await env.DB.prepare(`SELECT id FROM hr_employment_profiles WHERE organization_id=? AND dba_id=? AND person_id=?`).bind(authz.organizationId,authz.dbaId,personId).first();let id;if(existing){id=existing.id;await env.DB.prepare(`UPDATE hr_employment_profiles SET position_id=?,manager_person_id=?,hire_date=?,employment_status=?,pay_type=?,hourly_rate_cents=?,annual_salary_cents=?,overtime_eligible=?,standard_hours_week=?,pay_schedule=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(positionId,managerId,hireDate,employmentStatus,payType,hourly,salary,overtime,hours,schedule,id).run()}else{id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO hr_employment_profiles(id,organization_id,dba_id,person_id,position_id,manager_person_id,hire_date,employment_status,pay_type,hourly_rate_cents,annual_salary_cents,overtime_eligible,standard_hours_week,pay_schedule,created_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,authz.organizationId,authz.dbaId,personId,positionId,managerId,hireDate,employmentStatus,payType,hourly,salary,overtime,hours,schedule,authz.session.user_id).run()}if(employmentStatus==='active'&&person.status==='onboarding')await env.DB.prepare(`UPDATE hr_people SET status='active',hired_at=COALESCE(hired_at,?),updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(hireDate,personId).run();const auditRecorded=await auditMutation(env,authz,'hr.employment.upsert','hr_employment_profile',id,{personId,payType,schedule,employmentStatus});return json({ok:true,employment:{id,personId,payType,paySchedule:schedule,employmentStatus},auditRecorded})}

async function listJobs(request,env){const gate=await authorize(request,env,'module.read','hr.recruiting.jobs.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT j.id,j.title,j.department,j.location,j.employment_type,j.status,j.opened_at,j.closed_at,j.created_at,COUNT(a.id) AS applications,SUM(CASE WHEN a.stage='offer' THEN 1 ELSE 0 END) AS offers,SUM(CASE WHEN a.stage='hired' THEN 1 ELSE 0 END) AS hires FROM hr_jobs j LEFT JOIN hr_applications a ON a.job_id=j.id WHERE j.organization_id=? AND j.dba_id=? GROUP BY j.id ORDER BY CASE j.status WHEN 'open' THEN 0 WHEN 'draft' THEN 1 ELSE 2 END,j.created_at DESC`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,jobs:rows.results||[]})}
async function createJob(request,env){const gate=await authorize(request,env,'module.write','hr.recruiting.job.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,title=text(b.title,180),type=text(b.employmentType||'full_time',30),status=text(b.status||'open',20);if(title.length<2||!EMPLOYMENT_TYPES.has(type)||!['draft','open'].includes(status))return json({ok:false,error:'valid_job_fields_required'},400);const id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO hr_jobs(id,organization_id,dba_id,title,department,location,employment_type,description,status,opened_at,created_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(id,authz.organizationId,authz.dbaId,title,nullableText(b.department,160),nullableText(b.location,200),type,nullableText(b.description,4000),status,status==='open'?new Date().toISOString():null,authz.session.user_id).run();const auditRecorded=await auditMutation(env,authz,'hr.job.create','hr_job',id,{title,status});return json({ok:true,job:{id,title,status,employmentType:type},auditRecorded},201)}
async function listApplications(request,env){const gate=await authorize(request,env,'module.read','hr.recruiting.applications.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT a.id,a.job_id,j.title AS job_title,a.person_id,p.display_name,p.email,a.stage,a.source,a.score,a.notes,a.created_at,a.updated_at FROM hr_applications a JOIN hr_jobs j ON j.id=a.job_id JOIN hr_people p ON p.id=a.person_id WHERE a.organization_id=? AND a.dba_id=? ORDER BY a.updated_at DESC`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,applications:rows.results||[]})}
async function createApplication(request,env){const gate=await authorize(request,env,'module.write','hr.recruiting.application.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,jobId=text(b.jobId,128),first=text(b.firstName,100),last=text(b.lastName,100),display=text(b.displayName||`${first} ${last}`,220),normalizedEmail=b.email?email(b.email):null;if(!jobId||!first||!last||display.length<2||(b.email&&!normalizedEmail))return json({ok:false,error:'valid_candidate_fields_required'},400);const job=await env.DB.prepare(`SELECT id FROM hr_jobs WHERE id=? AND organization_id=? AND dba_id=? AND status='open'`).bind(jobId,authz.organizationId,authz.dbaId).first();if(!job)return json({ok:false,error:'open_job_not_found'},404);let person=null;if(normalizedEmail)person=await env.DB.prepare(`SELECT id FROM hr_people WHERE organization_id=? AND dba_id=? AND lower(email)=lower(?)`).bind(authz.organizationId,authz.dbaId,normalizedEmail).first();const personId=person?.id||crypto.randomUUID(),appId=crypto.randomUUID();const ops=[];if(!person)ops.push(env.DB.prepare(`INSERT INTO hr_people(id,organization_id,dba_id,person_type,first_name,last_name,display_name,email,status,created_by_user_id) VALUES(?,?,?,'candidate',?,?,?,?, 'active',?)`).bind(personId,authz.organizationId,authz.dbaId,first,last,display,normalizedEmail,authz.session.user_id));ops.push(env.DB.prepare(`INSERT INTO hr_applications(id,organization_id,dba_id,job_id,person_id,stage,source,notes,created_by_user_id) VALUES(?,?,?,?,?,'applied',?,?,?)`).bind(appId,authz.organizationId,authz.dbaId,jobId,personId,nullableText(b.source,120),nullableText(b.notes,1000),authz.session.user_id));try{await env.DB.batch(ops)}catch{return json({ok:false,error:'application_conflict'},409)}const auditRecorded=await auditMutation(env,authz,'hr.application.create','hr_application',appId,{jobId,personId});return json({ok:true,application:{id:appId,jobId,personId,stage:'applied'},auditRecorded},201)}
async function stageApplication(request,env,id){const gate=await authorize(request,env,'module.write','hr.recruiting.application.stage');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const stage=text(parsed.body?.stage,30);if(!APP_STAGES.has(stage))return json({ok:false,error:'invalid_application_stage'},400);const app=await env.DB.prepare(`SELECT * FROM hr_applications WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!app)return json({ok:false,error:'application_not_found'},404);const ops=[env.DB.prepare(`UPDATE hr_applications SET stage=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(stage,id)];if(stage==='hired'){ops.push(env.DB.prepare(`UPDATE hr_people SET person_type='employee',status='onboarding',updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(app.person_id));for(const title of ['Complete employment profile','Review company policies','Complete required onboarding training'])ops.push(env.DB.prepare(`INSERT INTO hr_onboarding_tasks(id,organization_id,dba_id,person_id,title,status,created_by_user_id) VALUES(?,?,?,?,?,'pending',?)`).bind(crypto.randomUUID(),authz.organizationId,authz.dbaId,app.person_id,title,authz.session.user_id))}if(stage==='rejected')ops.push(env.DB.prepare(`UPDATE hr_people SET status='rejected',updated_at=CURRENT_TIMESTAMP WHERE id=? AND person_type='candidate'`).bind(app.person_id));await env.DB.batch(ops);const auditRecorded=await auditMutation(env,authz,'hr.application.stage','hr_application',id,{stage,personId:app.person_id});return json({ok:true,application:{id,stage},auditRecorded})}

async function listTime(request,env,url){const gate=await authorize(request,env,'module.read','hr.time.read');if(gate.response)return gate.response;const{authz}=gate,from=isoDate(url.searchParams.get('from'))||new Date(Date.now()-30*86400000).toISOString().slice(0,10),to=isoDate(url.searchParams.get('to'))||new Date().toISOString().slice(0,10);const rows=await env.DB.prepare(`SELECT t.id,t.person_id,p.display_name,t.work_date,t.regular_minutes,t.overtime_minutes,t.notes,t.status,t.approved_at,t.created_at FROM hr_time_entries t JOIN hr_people p ON p.id=t.person_id WHERE t.organization_id=? AND t.dba_id=? AND t.work_date BETWEEN ? AND ? ORDER BY t.work_date DESC,p.display_name`).bind(authz.organizationId,authz.dbaId,from,to).all();return json({ok:true,period:{from,to},timeEntries:rows.results||[]})}
async function createTime(request,env){const gate=await authorize(request,env,'module.write','hr.time.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,personId=text(b.personId,128),date=isoDate(b.workDate),regular=safeInt(b.regularMinutes??0,{min:0,max:1440}),overtime=safeInt(b.overtimeMinutes??0,{min:0,max:1440});if(!personId||!date||regular==null||overtime==null||regular+overtime>1440||regular+overtime===0)return json({ok:false,error:'valid_time_entry_required'},400);const person=await personInScope(env,authz,personId);if(!person||!['employee','contractor','intern'].includes(person.person_type))return json({ok:false,error:'worker_not_found'},404);const id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO hr_time_entries(id,organization_id,dba_id,person_id,work_date,regular_minutes,overtime_minutes,notes,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,?, 'submitted',?)`).bind(id,authz.organizationId,authz.dbaId,personId,date,regular,overtime,nullableText(b.notes,1000),authz.session.user_id).run();const auditRecorded=await auditMutation(env,authz,'hr.time.create','hr_time_entry',id,{personId,date,regularMinutes:regular,overtimeMinutes:overtime});return json({ok:true,timeEntry:{id,personId,workDate:date,regularMinutes:regular,overtimeMinutes:overtime,status:'submitted'},auditRecorded},201)}
async function approveTime(request,env,id){const gate=await authorize(request,env,'module.write','hr.time.approve');if(gate.response)return gate.response;const{authz}=gate;if(!['owner','admin','manager'].includes(authz.membership?.role))return json({ok:false,error:'time_approval_role_required'},403);const row=await env.DB.prepare(`SELECT id,status FROM hr_time_entries WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!row)return json({ok:false,error:'time_entry_not_found'},404);if(row.status!=='submitted')return json({ok:false,error:'time_entry_not_submitted'},409);await env.DB.prepare(`UPDATE hr_time_entries SET status='approved',approved_by_user_id=?,approved_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(authz.session.user_id,id).run();const auditRecorded=await auditMutation(env,authz,'hr.time.approve','hr_time_entry',id);return json({ok:true,timeEntry:{id,status:'approved'},auditRecorded})}

async function listPayRuns(request,env){const gate=await authorize(request,env,'module.read','hr.payroll.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT id,period_start,period_end,pay_date,status,gross_cents,deductions_cents,employee_tax_cents,net_cents,approved_at,paid_at,created_at FROM hr_pay_runs WHERE organization_id=? AND dba_id=? ORDER BY pay_date DESC,created_at DESC`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,payRuns:rows.results||[]})}
async function createPayRun(request,env){const gate=await authorize(request,env,'module.write','hr.payroll.run.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const b=parsed.body,start=isoDate(b.periodStart),end=isoDate(b.periodEnd),payDate=isoDate(b.payDate);if(!start||!end||!payDate||start>end)return json({ok:false,error:'valid_pay_period_required'},400);const id=crypto.randomUUID();try{await env.DB.prepare(`INSERT INTO hr_pay_runs(id,organization_id,dba_id,period_start,period_end,pay_date,status,created_by_user_id) VALUES(?,?,?,?,?,?,'draft',?)`).bind(id,authz.organizationId,authz.dbaId,start,end,payDate,authz.session.user_id).run()}catch{return json({ok:false,error:'pay_run_conflict'},409)}const auditRecorded=await auditMutation(env,authz,'hr.payroll.run.create','hr_pay_run',id,{periodStart:start,periodEnd:end,payDate});return json({ok:true,payRun:{id,periodStart:start,periodEnd:end,payDate,status:'draft'},auditRecorded},201)}
async function calculatePayRun(request,env,id){const gate=await authorize(request,env,'module.write','hr.payroll.calculate');if(gate.response)return gate.response;const{authz}=gate;const run=await env.DB.prepare(`SELECT * FROM hr_pay_runs WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!run)return json({ok:false,error:'pay_run_not_found'},404);if(!['draft','calculated'].includes(run.status))return json({ok:false,error:'pay_run_not_recalculable'},409);const workers=await env.DB.prepare(`SELECT e.*,p.display_name FROM hr_employment_profiles e JOIN hr_people p ON p.id=e.person_id WHERE e.organization_id=? AND e.dba_id=? AND e.employment_status='active' AND p.status IN ('active','onboarding')`).bind(authz.organizationId,authz.dbaId).all();const ops=[env.DB.prepare(`DELETE FROM hr_pay_run_items WHERE pay_run_id=?`).bind(id)];let grossTotal=0;for(const w of workers.results||[]){let regularMinutes=0,overtimeMinutes=0,regularPay=0,overtimePay=0;if(w.pay_type==='hourly'){const t=await env.DB.prepare(`SELECT COALESCE(SUM(regular_minutes),0) AS regular,COALESCE(SUM(overtime_minutes),0) AS overtime FROM hr_time_entries WHERE organization_id=? AND dba_id=? AND person_id=? AND work_date BETWEEN ? AND ? AND status='approved'`).bind(authz.organizationId,authz.dbaId,w.person_id,run.period_start,run.period_end).first();regularMinutes=Number(t?.regular||0);overtimeMinutes=Number(t?.overtime||0);const rate=Number(w.hourly_rate_cents||0);regularPay=Math.round(regularMinutes*rate/60);overtimePay=Math.round(overtimeMinutes*rate*(Number(w.overtime_eligible)===1?1.5:1)/60)}else if(w.pay_type==='salary'){const periods={weekly:52,biweekly:26,semimonthly:24,monthly:12}[w.pay_schedule]||26;regularPay=Math.round(Number(w.annual_salary_cents||0)/periods)}const gross=regularPay+overtimePay,net=gross;grossTotal+=gross;ops.push(env.DB.prepare(`INSERT INTO hr_pay_run_items(id,pay_run_id,organization_id,dba_id,person_id,regular_minutes,overtime_minutes,regular_pay_cents,overtime_pay_cents,gross_cents,net_cents) VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(crypto.randomUUID(),id,authz.organizationId,authz.dbaId,w.person_id,regularMinutes,overtimeMinutes,regularPay,overtimePay,gross,net))}ops.push(env.DB.prepare(`UPDATE hr_pay_runs SET status='calculated',gross_cents=?,deductions_cents=0,employee_tax_cents=0,net_cents=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(grossTotal,grossTotal,id));await env.DB.batch(ops);const auditRecorded=await auditMutation(env,authz,'hr.payroll.calculate','hr_pay_run',id,{workers:(workers.results||[]).length,grossCents:grossTotal,withholding:'not_configured'});return json({ok:true,payRun:{id,status:'calculated',grossCents:grossTotal,netCents:grossTotal,withholdingStatus:'not_configured'},auditRecorded})}
async function payRunDetail(request,env,id){const gate=await authorize(request,env,'module.read','hr.payroll.read');if(gate.response)return gate.response;const{authz}=gate;const run=await env.DB.prepare(`SELECT * FROM hr_pay_runs WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!run)return json({ok:false,error:'pay_run_not_found'},404);const items=await env.DB.prepare(`SELECT i.*,p.display_name FROM hr_pay_run_items i JOIN hr_people p ON p.id=i.person_id WHERE i.pay_run_id=? ORDER BY p.display_name`).bind(id).all();return json({ok:true,payRun:run,items:items.results||[],withholdingStatus:'manual_configuration_required'})}
async function adjustPayItem(request,env,runId,itemId){const gate=await authorize(request,env,'module.write','hr.payroll.item.adjust');if(gate.response)return gate.response;const{authz}=gate;const run=await env.DB.prepare(`SELECT * FROM hr_pay_runs WHERE id=? AND organization_id=? AND dba_id=?`).bind(runId,authz.organizationId,authz.dbaId).first();if(!run)return json({ok:false,error:'pay_run_not_found'},404);if(run.status!=='calculated')return json({ok:false,error:'pay_run_not_editable'},409);const item=await env.DB.prepare(`SELECT * FROM hr_pay_run_items WHERE id=? AND pay_run_id=? AND organization_id=? AND dba_id=?`).bind(itemId,runId,authz.organizationId,authz.dbaId).first();if(!item)return json({ok:false,error:'pay_item_not_found'},404);const parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const pre=safeInt(parsed.body?.pretaxDeductionsCents??item.pretax_deductions_cents,{min:0}),tax=safeInt(parsed.body?.employeeTaxCents??item.employee_tax_cents,{min:0}),post=safeInt(parsed.body?.posttaxDeductionsCents??item.posttax_deductions_cents,{min:0});if(pre==null||tax==null||post==null||pre+tax+post>Number(item.gross_cents))return json({ok:false,error:'invalid_payroll_deductions'},400);const net=Number(item.gross_cents)-pre-tax-post;await env.DB.prepare(`UPDATE hr_pay_run_items SET pretax_deductions_cents=?,employee_tax_cents=?,posttax_deductions_cents=?,net_cents=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(pre,tax,post,net,itemId).run();const totals=await recomputePayRun(env,runId);const auditRecorded=await auditMutation(env,authz,'hr.payroll.item.adjust','hr_pay_run_item',itemId,{runId,pretaxDeductionsCents:pre,employeeTaxCents:tax,posttaxDeductionsCents:post});return json({ok:true,item:{id:itemId,netCents:net},totals,auditRecorded})}
async function approvePayRun(request,env,id){const gate=await authorize(request,env,'module.write','hr.payroll.approve');if(gate.response)return gate.response;const{authz}=gate;if(!['owner','admin','manager'].includes(authz.membership?.role))return json({ok:false,error:'payroll_approval_role_required'},403);const run=await env.DB.prepare(`SELECT * FROM hr_pay_runs WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!run)return json({ok:false,error:'pay_run_not_found'},404);if(run.status!=='calculated')return json({ok:false,error:'pay_run_not_calculated'},409);await env.DB.prepare(`UPDATE hr_pay_runs SET status='approved',approved_by_user_id=?,approved_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(authz.session.user_id,id).run();const auditRecorded=await auditMutation(env,authz,'hr.payroll.approve','hr_pay_run',id,{grossCents:run.gross_cents,netCents:run.net_cents});return json({ok:true,payRun:{id,status:'approved'},auditRecorded})}
async function markPayRunPaid(request,env,id){const gate=await authorize(request,env,'module.write','hr.payroll.mark_paid');if(gate.response)return gate.response;const{authz}=gate;if(!['owner','admin'].includes(authz.membership?.role))return json({ok:false,error:'owner_or_admin_required'},403);const run=await env.DB.prepare(`SELECT * FROM hr_pay_runs WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!run)return json({ok:false,error:'pay_run_not_found'},404);if(run.status!=='approved')return json({ok:false,error:'pay_run_not_approved'},409);await env.DB.prepare(`UPDATE hr_pay_runs SET status='paid',paid_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(id).run();const auditRecorded=await auditMutation(env,authz,'hr.payroll.mark_paid','hr_pay_run',id,{recordOnly:true});return json({ok:true,payRun:{id,status:'paid',moneyMovementPerformed:false},auditRecorded})}

async function listOnboarding(request,env){const gate=await authorize(request,env,'module.read','hr.onboarding.read');if(gate.response)return gate.response;const{authz}=gate;const rows=await env.DB.prepare(`SELECT t.id,t.person_id,p.display_name,t.title,t.due_date,t.status,t.completed_at,t.notes,t.created_at FROM hr_onboarding_tasks t JOIN hr_people p ON p.id=t.person_id WHERE t.organization_id=? AND t.dba_id=? ORDER BY CASE t.status WHEN 'pending' THEN 0 WHEN 'in_progress' THEN 1 ELSE 2 END,COALESCE(t.due_date,'9999-12-31'),p.display_name`).bind(authz.organizationId,authz.dbaId).all();return json({ok:true,tasks:rows.results||[]})}
async function createOnboarding(request,env){const gate=await authorize(request,env,'module.write','hr.onboarding.create');if(gate.response)return gate.response;const{authz}=gate,parsed=await bodyJson(request);if(!parsed.ok)return json({ok:false,error:parsed.error},parsed.status);const personId=text(parsed.body?.personId,128),title=text(parsed.body?.title,220),due=parsed.body?.dueDate?isoDate(parsed.body.dueDate):null;if(!personId||title.length<2||(parsed.body?.dueDate&&!due)||!await personInScope(env,authz,personId))return json({ok:false,error:'valid_onboarding_task_required'},400);const id=crypto.randomUUID();await env.DB.prepare(`INSERT INTO hr_onboarding_tasks(id,organization_id,dba_id,person_id,title,due_date,status,notes,created_by_user_id) VALUES(?,?,?,?,?,?,'pending',?,?)`).bind(id,authz.organizationId,authz.dbaId,personId,title,due,nullableText(parsed.body?.notes,1000),authz.session.user_id).run();const auditRecorded=await auditMutation(env,authz,'hr.onboarding.create','hr_onboarding_task',id,{personId,title});return json({ok:true,task:{id,personId,title,dueDate:due,status:'pending'},auditRecorded},201)}
async function completeOnboarding(request,env,id){const gate=await authorize(request,env,'module.write','hr.onboarding.complete');if(gate.response)return gate.response;const{authz}=gate;const task=await env.DB.prepare(`SELECT id,status FROM hr_onboarding_tasks WHERE id=? AND organization_id=? AND dba_id=?`).bind(id,authz.organizationId,authz.dbaId).first();if(!task)return json({ok:false,error:'onboarding_task_not_found'},404);if(['completed','waived'].includes(task.status))return json({ok:false,error:'onboarding_task_already_closed'},409);await env.DB.prepare(`UPDATE hr_onboarding_tasks SET status='completed',completed_at=CURRENT_TIMESTAMP,completed_by_user_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(authz.session.user_id,id).run();const auditRecorded=await auditMutation(env,authz,'hr.onboarding.complete','hr_onboarding_task',id);return json({ok:true,task:{id,status:'completed'},auditRecorded})}

const sections=[['overview','Overview','/platform/hr-payroll'],['employees','Employees','/platform/hr-payroll/employees'],['recruiting','Recruiting','/platform/hr-payroll/recruiting'],['time','Time & Attendance','/platform/hr-payroll/time'],['payroll','Payroll','/platform/hr-payroll/payroll'],['onboarding','Onboarding','/platform/hr-payroll/onboarding'],['benefits','Benefits','/platform/hr-payroll/benefits'],['performance','Performance','/platform/hr-payroll/performance'],['training','Training','/platform/hr-payroll/training']];
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const css=`:root{color-scheme:dark;--bg:#020711;--panel:#071522;--line:rgba(70,166,238,.24);--text:#f2f8fe;--muted:#8ca6ba;--cyan:#42cfff;--green:#51d17c;--orange:#f08a3c;--violet:#8b63df}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 88% 0,rgba(40,95,180,.18),transparent 30%),#020711;color:var(--text);font-family:Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:230px 1fr}.side{height:100vh;position:sticky;top:0;overflow:auto;padding:13px 10px;border-right:1px solid var(--line);background:linear-gradient(#030d18,#04111d 58%,#020a12)}.brand{display:flex;align-items:center;gap:10px;padding:13px 8px;border-bottom:1px solid var(--line);margin-bottom:9px}.mark{font-size:28px;font-weight:900;color:#63d5ff}.brand strong{letter-spacing:.22em}.brand small{display:block;color:#7096b0;font-size:.5rem}.side nav{display:grid;gap:3px}.side nav a{padding:9px 10px;border:1px solid transparent;border-radius:8px;color:#a9bdcc;font-size:.68rem}.side nav a.active,.side nav a:hover{border-color:#276fc0;background:#0a2a49;color:#fff}.main{min-width:0;padding:11px 14px 28px}.top{height:60px;position:sticky;top:0;z-index:20;display:flex;gap:10px;align-items:center;padding:8px 10px;border:1px solid var(--line);border-radius:11px;background:#05131fef;backdrop-filter:blur(18px)}.menu{display:none}.title{flex:1}.title b{display:block;font-size:.75rem;letter-spacing:.1em}.title span{display:block;color:#7896aa;font-size:.57rem}.scope select{height:37px;min-width:260px;border:1px solid var(--line);border-radius:8px;background:#081827;color:white;padding:0 9px}.head{margin:15px 0 11px}.eyebrow{font-size:.58rem;letter-spacing:.16em;color:var(--cyan);font-weight:800}.head h1{font-size:clamp(1.8rem,3vw,2.8rem);margin:6px 0 4px}.head p{margin:0;max-width:780px;color:var(--muted);font-size:.74rem;line-height:1.55}.notice{display:none;margin-bottom:10px;padding:10px 12px;border:1px solid #8a6928;border-radius:9px;background:#2c220d;color:#ffd98a;font-size:.66rem}.notice.show{display:block}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.kpi{padding:13px;border:1px solid var(--line);border-radius:10px;background:#071522}.kpi span{display:block;color:#8ba5b8;font-size:.58rem}.kpi strong{display:block;font-size:1.08rem;margin-top:5px}.grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:10px;margin-top:10px}.panel{border:1px solid var(--line);border-radius:11px;background:linear-gradient(145deg,#071725,#06131f);padding:14px;box-shadow:0 18px 55px #0006}.panel h2{margin:0 0 4px;font-size:.75rem;letter-spacing:.08em}.panel p{margin:5px 0 12px;color:#7f98ab;font-size:.62rem;line-height:1.5}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:10px}.card{padding:13px;border:1px solid var(--line);border-radius:9px;background:#081827}.card b{font-size:.7rem}.card p{color:#8199ac;font-size:.6rem;line-height:1.45}.card a{color:#43b9ff;font-size:.6rem}.form{display:grid;gap:8px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.form label{display:grid;gap:5px;color:#8ba7bb;font-size:.58rem}.form input,.form select,.form textarea{width:100%;padding:9px;border:1px solid var(--line);border-radius:8px;background:#081827;color:white}.form textarea{min-height:66px}.form button,.action{padding:8px 10px;border:1px solid #2f8bd8;border-radius:8px;background:#0e5cae;color:white;font-weight:700;cursor:pointer}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:.62rem}.table th,.table td{padding:9px 7px;border-bottom:1px solid rgba(68,147,205,.14);text-align:left;white-space:nowrap}.table th{color:#7f9cb2}.table td{color:#c6d6e0}.footer{margin-top:10px;padding:10px 12px;border:1px solid var(--line);border-radius:9px;color:#7896aa;font-size:.58rem}.good{color:var(--green)}.warn{color:var(--orange)}@media(max-width:1000px){.grid{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.kpis{grid-template-columns:1fr 1fr}}@media(max-width:820px){.shell{display:block}.side{position:fixed;left:0;top:0;width:min(82vw,292px);transform:translateX(-105%);transition:.2s;z-index:40;box-shadow:24px 0 60px #0009}.nav-open .side{transform:translateX(0)}.menu{display:block}.scope{display:none}.main{padding:8px}.row,.cards{grid-template-columns:1fr}}@media(max-width:520px){.kpis{grid-template-columns:1fr}}`;
function table(id,headers){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody id="${id}"></tbody></table></div>`}
function body(section){if(section==='overview')return `<section class="kpis"><article class="kpi"><span>Active people</span><strong id="kEmployees">—</strong></article><article class="kpi"><span>Open jobs</span><strong id="kJobs">—</strong></article><article class="kpi"><span>Time awaiting approval</span><strong id="kTime">—</strong></article><article class="kpi"><span>Onboarding tasks</span><strong id="kOnboarding">—</strong></article></section><section class="cards"><article class="card"><b>Employees</b><p>People, positions and compensation profiles.</p><a href="/platform/hr-payroll/employees">Open employees →</a></article><article class="card"><b>Recruiting</b><p>Open roles, candidates and hiring stages.</p><a href="/platform/hr-payroll/recruiting">Open recruiting →</a></article><article class="card"><b>Payroll</b><p>Pay periods, gross calculations and approval controls.</p><a href="/platform/hr-payroll/payroll">Open payroll →</a></article></section>`;if(section==='employees')return `<section class="grid"><article class="panel"><h2>EMPLOYEES</h2>${table('employeeRows',['Employee','Number','Department','Position','Status','Pay type','Rate / Salary'])}<h2 style="margin-top:18px">POSITIONS</h2>${table('positionRows',['Code','Position','Department','Type','Status'])}</article><aside class="panel"><h2>NEW EMPLOYEE</h2><form class="form" id="employeeForm"><div class="row"><label>First name<input name="firstName" required></label><label>Last name<input name="lastName" required></label></div><label>Email<input name="email" type="email"></label><div class="row"><label>Employee #<input name="employeeNumber"></label><label>Hire date<input name="hiredAt" type="date"></label></div><label>Department<input name="department"></label><label>Job title<input name="jobTitle"></label><button>Create employee</button></form><h2 style="margin-top:18px">NEW POSITION</h2><form class="form" id="positionForm"><div class="row"><label>Code<input name="code" required></label><label>Type<select name="employmentType"><option value="full_time">Full time</option><option value="part_time">Part time</option><option value="temporary">Temporary</option><option value="contract">Contract</option><option value="intern">Intern</option></select></label></div><label>Title<input name="title" required></label><label>Department<input name="department"></label><button>Create position</button></form></aside></section>`;if(section==='recruiting')return `<section class="grid"><article class="panel"><h2>OPEN ROLES</h2>${table('jobRows',['Role','Department','Location','Status','Applications','Offers','Hires'])}<h2 style="margin-top:18px">CANDIDATES</h2>${table('applicationRows',['Candidate','Role','Stage','Source','Score','Action'])}</article><aside class="panel"><h2>NEW JOB</h2><form class="form" id="jobForm"><label>Title<input name="title" required></label><div class="row"><label>Department<input name="department"></label><label>Location<input name="location"></label></div><label>Employment type<select name="employmentType"><option value="full_time">Full time</option><option value="part_time">Part time</option><option value="temporary">Temporary</option><option value="contract">Contract</option><option value="intern">Intern</option></select></label><label>Description<textarea name="description"></textarea></label><button>Open job</button></form><h2 style="margin-top:18px">ADD CANDIDATE</h2><form class="form" id="candidateForm"><label>Open job<select name="jobId" id="candidateJob" required></select></label><div class="row"><label>First name<input name="firstName" required></label><label>Last name<input name="lastName" required></label></div><label>Email<input name="email" type="email"></label><label>Source<input name="source" placeholder="Referral, website…"></label><button>Add application</button></form></aside></section>`;if(section==='time')return `<section class="grid"><article class="panel"><h2>TIME & ATTENDANCE</h2><p>Approved time is the source for hourly payroll calculations.</p>${table('timeRows',['Date','Employee','Regular','Overtime','Status','Action'])}</article><aside class="panel"><h2>ADD TIME ENTRY</h2><form class="form" id="timeForm"><label>Employee<select name="personId" id="timePerson" required></select></label><label>Work date<input name="workDate" type="date" required></label><div class="row"><label>Regular hours<input name="regularHours" type="number" min="0" max="24" step="0.25" required></label><label>Overtime hours<input name="overtimeHours" type="number" min="0" max="24" step="0.25" value="0"></label></div><label>Notes<textarea name="notes"></textarea></label><button>Submit time</button></form></aside></section>`;if(section==='payroll')return `<section class="grid"><article class="panel"><h2>PAY RUNS</h2><p>Gross wages calculate from configured salary profiles or approved hourly time. Tax withholding remains explicit/manual until jurisdictional payroll tax tables are configured.</p>${table('payRows',['Period','Pay date','Gross','Deductions','Tax','Net','Status','Action'])}<h2 style="margin-top:18px">PAY RUN DETAIL</h2>${table('payItemRows',['Employee','Regular','OT','Gross','Tax','Deductions','Net'])}</article><aside class="panel"><h2>NEW PAY RUN</h2><form class="form" id="payRunForm"><div class="row"><label>Period start<input name="periodStart" type="date" required></label><label>Period end<input name="periodEnd" type="date" required></label></div><label>Pay date<input name="payDate" type="date" required></label><button>Create draft pay run</button></form><div class="footer">Marking a run “Paid” records payroll status only. ATLAS does not move money from this screen.</div></aside></section>`;if(section==='onboarding')return `<section class="grid"><article class="panel"><h2>ONBOARDING TASKS</h2>${table('onboardingRows',['Employee','Task','Due','Status','Action'])}</article><aside class="panel"><h2>NEW TASK</h2><form class="form" id="onboardingForm"><label>Employee<select name="personId" id="onboardingPerson" required></select></label><label>Task<input name="title" required></label><label>Due date<input name="dueDate" type="date"></label><label>Notes<textarea name="notes"></textarea></label><button>Add task</button></form></aside></section>`;const title={benefits:'Benefits',performance:'Performance',training:'Training'}[section]||'HR';return `<section class="panel"><h2>${title.toUpperCase()}</h2><p>This workspace is connected to the HR & Payroll navigation and protected scope. The next HR increment will add ${title.toLowerCase()} records and workflows without changing the approved dashboard family.</p></section>`}
function page(section){const title=sections.find(x=>x[0]===section)?.[1]||'HR & Payroll';return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#020711"><title>${esc(title)} · ATLAS HR</title><style>${css}</style></head><body><div class="shell"><aside class="side"><a class="brand" href="/dashboard"><span class="mark">A</span><span><strong>ATLAS</strong><small>ENTERPRISE SUITE</small></span></a><nav>${sections.map(([id,label,href])=>`<a class="${id===section?'active':''}" href="${href}">${esc(label)}</a>`).join('')}</nav></aside><main class="main"><header class="top"><button class="menu" id="menuBtn">☰</button><div class="title"><b>ATLAS HR & PAYROLL</b><span>${esc(title)} · v${ATLAS_VERSION}</span></div><label class="scope"><select id="scopeSelect"><option>Loading company context…</option></select></label></header><section class="head"><div class="eyebrow">PEOPLE OPERATIONS · ${esc(title).toUpperCase()}</div><h1>${esc(title)}</h1><p>Employees, recruiting, time, payroll and onboarding share the same authenticated organization and DBA boundaries used across ATLAS.</p></section><div class="notice" id="notice"></div>${body(section)}<footer class="footer">ATLAS HR & Payroll · secure session · scoped data · audit ledger</footer></main></div><script>(()=>{const root=document.documentElement,menu=document.getElementById('menuBtn'),notice=document.getElementById('notice'),scopeSelect=document.getElementById('scopeSelect');menu?.addEventListener('click',()=>root.classList.toggle('nav-open'));const token=(()=>{try{return sessionStorage.getItem('atlas.session')||''}catch{return''}})();let scopes=[],scope=null;const show=m=>{notice.textContent=m;notice.classList.add('show')},clear=()=>{notice.textContent='';notice.classList.remove('show')},money=c=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(Number(c||0)/100),hours=m=>(Number(m||0)/60).toFixed(2),toCents=v=>Math.round(Number(v||0)*100),req=async(path,options={})=>{if(!token)throw new Error('Re-authenticate in this tab to use live HR data.');if(!scope)throw new Error('No company scope selected.');const h=new Headers(options.headers||{});h.set('authorization','Bearer '+token);h.set('x-atlas-organization',scope.organization.id);h.set('x-atlas-dba',scope.dba.id);if(options.body)h.set('content-type','application/json');const r=await fetch(path,{...options,headers:h,cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(d.error||'Request failed');e.data=d;throw e}return d},fill=(id,items,value,label)=>{const s=document.getElementById(id);if(!s)return;s.textContent='';(items||[]).forEach(x=>{const o=document.createElement('option');o.value=value(x);o.textContent=label(x);s.appendChild(o)})},rows=(id,data,mapper)=>{const b=document.getElementById(id);if(!b)return;b.textContent='';(data||[]).forEach(x=>{const tr=document.createElement('tr');mapper(x).forEach(v=>{const td=document.createElement('td');if(v instanceof Node)td.appendChild(v);else td.textContent=String(v??'');tr.appendChild(td)});b.appendChild(tr)})};const employees=async()=>{const d=await req('/api/hr-payroll/employees');return d.employees||[]};const loadOverview=async()=>{const d=await req('/api/hr-payroll/overview'),o=d.overview;document.getElementById('kEmployees').textContent=String(o.employees);document.getElementById('kJobs').textContent=String(o.openJobs);document.getElementById('kTime').textContent=String(o.timeAwaitingApproval);document.getElementById('kOnboarding').textContent=String(o.onboardingOpen)};const loadEmployees=async()=>{const[e,p]=await Promise.all([req('/api/hr-payroll/employees'),req('/api/hr-payroll/positions')]);rows('employeeRows',e.employees,x=>[x.display_name,x.employee_number||'',x.department||'',x.position_title||x.job_title||'',x.status,x.pay_type||'Not configured',x.pay_type==='hourly'?money(x.hourly_rate_cents)+'/hr':x.pay_type==='salary'?money(x.annual_salary_cents)+'/yr':'—']);rows('positionRows',p.positions,x=>[x.code,x.title,x.department||'',x.employment_type,x.status])};const loadRecruiting=async()=>{const[j,a]=await Promise.all([req('/api/hr-payroll/jobs'),req('/api/hr-payroll/applications')]);rows('jobRows',j.jobs,x=>[x.title,x.department||'',x.location||'',x.status,x.applications||0,x.offers||0,x.hires||0]);rows('applicationRows',a.applications,x=>{const sel=document.createElement('select');['applied','screening','interview','assessment','offer','hired','rejected','withdrawn'].forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;o.selected=s===x.stage;sel.appendChild(o)});sel.onchange=async()=>{try{await req('/api/hr-payroll/applications/'+x.id+'/stage',{method:'POST',body:JSON.stringify({stage:sel.value})});await loadRecruiting()}catch(e){show(e.message)}};return[x.display_name,x.job_title,x.stage,x.source||'',x.score??'',sel]});fill('candidateJob',(j.jobs||[]).filter(x=>x.status==='open'),x=>x.id,x=>x.title)};const loadTime=async()=>{const[e,t]=await Promise.all([employees(),req('/api/hr-payroll/time')]);fill('timePerson',e.filter(x=>['active','onboarding'].includes(x.status)),x=>x.id,x=>x.display_name);rows('timeRows',t.timeEntries,x=>{const box=document.createElement('div');if(x.status==='submitted'){const b=document.createElement('button');b.className='action';b.textContent='Approve';b.onclick=async()=>{try{await req('/api/hr-payroll/time/'+x.id+'/approve',{method:'POST'});await loadTime()}catch(e){show(e.message)}};box.appendChild(b)}else box.textContent='—';return[x.work_date,x.display_name,hours(x.regular_minutes),hours(x.overtime_minutes),x.status,box]})};const loadPayroll=async()=>{const d=await req('/api/hr-payroll/pay-runs');rows('payRows',d.payRuns,x=>{const box=document.createElement('div'),view=document.createElement('button');view.className='action';view.textContent='View';view.onclick=()=>loadPayDetail(x.id);box.appendChild(view);if(['draft','calculated'].includes(x.status)){const c=document.createElement('button');c.className='action';c.textContent='Calculate';c.onclick=async()=>{try{await req('/api/hr-payroll/pay-runs/'+x.id+'/calculate',{method:'POST'});await loadPayroll();await loadPayDetail(x.id)}catch(e){show(e.message)}};box.appendChild(c)}if(x.status==='calculated'){const a=document.createElement('button');a.className='action';a.textContent='Approve';a.onclick=async()=>{try{await req('/api/hr-payroll/pay-runs/'+x.id+'/approve',{method:'POST'});await loadPayroll()}catch(e){show(e.message)}};box.appendChild(a)}if(x.status==='approved'){const p=document.createElement('button');p.className='action';p.textContent='Mark paid';p.onclick=async()=>{try{await req('/api/hr-payroll/pay-runs/'+x.id+'/paid',{method:'POST'});await loadPayroll()}catch(e){show(e.message)}};box.appendChild(p)}return[x.period_start+' → '+x.period_end,x.pay_date,money(x.gross_cents),money(x.deductions_cents),money(x.employee_tax_cents),money(x.net_cents),x.status,box]})};const loadPayDetail=async id=>{const d=await req('/api/hr-payroll/pay-runs/'+id);rows('payItemRows',d.items,x=>[x.display_name,hours(x.regular_minutes),hours(x.overtime_minutes),money(x.gross_cents),money(x.employee_tax_cents),money(Number(x.pretax_deductions_cents)+Number(x.posttax_deductions_cents)),money(x.net_cents)])};const loadOnboarding=async()=>{const[e,t]=await Promise.all([employees(),req('/api/hr-payroll/onboarding')]);fill('onboardingPerson',e.filter(x=>x.status==='onboarding'||x.status==='active'),x=>x.id,x=>x.display_name);rows('onboardingRows',t.tasks,x=>{const box=document.createElement('div');if(!['completed','waived'].includes(x.status)){const b=document.createElement('button');b.className='action';b.textContent='Complete';b.onclick=async()=>{try{await req('/api/hr-payroll/onboarding/'+x.id+'/complete',{method:'POST'});await loadOnboarding()}catch(e){show(e.message)}};box.appendChild(b)}else box.textContent='—';return[x.display_name,x.title,x.due_date||'',x.status,box]})};const load=async()=>{clear();const p=location.pathname;if(p==='/platform/hr-payroll')return loadOverview();if(p.endsWith('/employees'))return loadEmployees();if(p.endsWith('/recruiting'))return loadRecruiting();if(p.endsWith('/time'))return loadTime();if(p.endsWith('/payroll'))return loadPayroll();if(p.endsWith('/onboarding'))return loadOnboarding()};document.getElementById('employeeForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/employees',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadEmployees()}catch(x){show(x.message)}});document.getElementById('positionForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/positions',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadEmployees()}catch(x){show(x.message)}});document.getElementById('jobForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/jobs',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadRecruiting()}catch(x){show(x.message)}});document.getElementById('candidateForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/applications',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadRecruiting()}catch(x){show(x.message)}});document.getElementById('timeForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/time',{method:'POST',body:JSON.stringify({personId:f.get('personId'),workDate:f.get('workDate'),regularMinutes:Math.round(Number(f.get('regularHours'))*60),overtimeMinutes:Math.round(Number(f.get('overtimeHours'))*60),notes:f.get('notes')})});e.currentTarget.reset();await loadTime()}catch(x){show(x.message)}});document.getElementById('payRunForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/pay-runs',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadPayroll()}catch(x){show(x.message)}});document.getElementById('onboardingForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await req('/api/hr-payroll/onboarding',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});e.currentTarget.reset();await loadOnboarding()}catch(x){show(x.message)}});const init=async()=>{if(!token){scopeSelect.innerHTML='<option>Re-authentication required</option>';show('The protected browser session is active, but live HR operations require the authenticated token in this tab.');return}const r=await fetch('/api/core/context',{headers:{authorization:'Bearer '+token},cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load company context');scopes=d.scopes||[];if(!scopes.length)throw new Error('No organization / DBA scope is assigned.');scopeSelect.textContent='';scopes.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s.organization.name+' · '+s.dba.name+' ('+s.role+')';scopeSelect.appendChild(o)});scope= scopes[0];scopeSelect.onchange=()=>{scope=scopes[Number(scopeSelect.value)||0];load().catch(e=>show(e.message))};const today=new Date().toISOString().slice(0,10);document.querySelectorAll('input[type=date]').forEach(i=>{if(!i.value)i.value=today});await load()};init().catch(e=>show(e.message||'Unable to initialize HR & Payroll'))})();</script></body></html>`}
function sectionFromPath(path){if(path==='/platform/hr-payroll')return'overview';const id=path.replace('/platform/hr-payroll/','');return sections.some(x=>x[0]===id)?id:'overview'}

export async function hrPayrollRoutes(request,env,url=new URL(request.url)){
 const path=url.pathname.length>1?url.pathname.replace(/\/+$/,''):url.pathname;
 if(path==='/api/hr-payroll/overview'&&request.method==='GET')return overview(request,env);
 if(path==='/api/hr-payroll/employees'&&request.method==='GET')return listEmployees(request,env);
 if(path==='/api/hr-payroll/employees'&&request.method==='POST')return createEmployee(request,env);
 const employment=path.match(/^\/api\/hr-payroll\/employees\/([^/]+)\/employment$/);if(employment&&request.method==='POST')return upsertEmployment(request,env,decodeURIComponent(employment[1]));
 if(path==='/api/hr-payroll/positions'&&request.method==='GET')return listPositions(request,env);
 if(path==='/api/hr-payroll/positions'&&request.method==='POST')return createPosition(request,env);
 if(path==='/api/hr-payroll/jobs'&&request.method==='GET')return listJobs(request,env);
 if(path==='/api/hr-payroll/jobs'&&request.method==='POST')return createJob(request,env);
 if(path==='/api/hr-payroll/applications'&&request.method==='GET')return listApplications(request,env);
 if(path==='/api/hr-payroll/applications'&&request.method==='POST')return createApplication(request,env);
 const appStage=path.match(/^\/api\/hr-payroll\/applications\/([^/]+)\/stage$/);if(appStage&&request.method==='POST')return stageApplication(request,env,decodeURIComponent(appStage[1]));
 if(path==='/api/hr-payroll/time'&&request.method==='GET')return listTime(request,env,url);
 if(path==='/api/hr-payroll/time'&&request.method==='POST')return createTime(request,env);
 const timeApprove=path.match(/^\/api\/hr-payroll\/time\/([^/]+)\/approve$/);if(timeApprove&&request.method==='POST')return approveTime(request,env,decodeURIComponent(timeApprove[1]));
 if(path==='/api/hr-payroll/pay-runs'&&request.method==='GET')return listPayRuns(request,env);
 if(path==='/api/hr-payroll/pay-runs'&&request.method==='POST')return createPayRun(request,env);
 const payDetail=path.match(/^\/api\/hr-payroll\/pay-runs\/([^/]+)$/);if(payDetail&&request.method==='GET')return payRunDetail(request,env,decodeURIComponent(payDetail[1]));
 const calculate=path.match(/^\/api\/hr-payroll\/pay-runs\/([^/]+)\/calculate$/);if(calculate&&request.method==='POST')return calculatePayRun(request,env,decodeURIComponent(calculate[1]));
 const approve=path.match(/^\/api\/hr-payroll\/pay-runs\/([^/]+)\/approve$/);if(approve&&request.method==='POST')return approvePayRun(request,env,decodeURIComponent(approve[1]));
 const paid=path.match(/^\/api\/hr-payroll\/pay-runs\/([^/]+)\/paid$/);if(paid&&request.method==='POST')return markPayRunPaid(request,env,decodeURIComponent(paid[1]));
 const item=path.match(/^\/api\/hr-payroll\/pay-runs\/([^/]+)\/items\/([^/]+)$/);if(item&&request.method==='PATCH')return adjustPayItem(request,env,decodeURIComponent(item[1]),decodeURIComponent(item[2]));
 if(path==='/api/hr-payroll/onboarding'&&request.method==='GET')return listOnboarding(request,env);
 if(path==='/api/hr-payroll/onboarding'&&request.method==='POST')return createOnboarding(request,env);
 const complete=path.match(/^\/api\/hr-payroll\/onboarding\/([^/]+)\/complete$/);if(complete&&request.method==='POST')return completeOnboarding(request,env,decodeURIComponent(complete[1]));
 if(request.method==='GET'&&(path==='/platform/hr-payroll'||path.startsWith('/platform/hr-payroll/')))return html(page(sectionFromPath(path)));
 return null;
}
